package it.farmacidicasa;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import android.text.*;import android.net.Uri;import org.json.*;import java.io.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 static final int GREEN=0xff117969,INK=0xff183730,MUTED=0xff64766f,BG=0xfff4f7f5;
 Store store;Catalog catalog;LinearLayout page,body;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler handler=new Handler(Looper.getMainLooper());int searchVersion=0;boolean alive=true;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);store=new Store(this);shell("Farmaci di casa","Il tuo armadietto, in ordine");text(body,"Preparazione del catalogo offline…",18,INK);worker.execute(()->{try {Catalog c=new Catalog(this);runOnUiThread(()->{if(!alive){c.close();return;}catalog=c;home();});}catch(Exception e){runOnUiThread(()->{if(alive)error("Catalogo non disponibile. Non è stato modificato l’inventario.\n"+e.getMessage());});}});ReminderReceiver.schedule(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},44);}
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(LinearLayout p,String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));p.addView(t);return t;}
 void button(LinearLayout p,String label,Runnable r){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(16);b.setBackground(bg(GREEN,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.setMargins(0,dp(8),0,dp(4));p.addView(b,lp);b.setOnClickListener(v->r.run());}
 LinearLayout card(LinearLayout parent){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),dp(12),dp(16),dp(12));l.setBackground(bg(Color.WHITE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(4));parent.addView(l,lp);return l;}
 void shell(String title,String subtitle){page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(BG);page.setPadding(dp(20),dp(12),dp(20),0);setContentView(page);page.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(dp(20),dp(12)+in.getSystemWindowInsetTop(),dp(20),in.getSystemWindowInsetBottom());return in;});page.requestApplyInsets();TextView h=text(page,title,28,INK);h.setTypeface(null,Typeface.BOLD);text(page,subtitle,14,MUTED);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(8),0,dp(24));sc.addView(body);page.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
 void home(){shell("Farmaci di casa","Il tuo armadietto, in ordine");List<JSONObject> all=store.boxes("");int soon=0,low=0;for(JSONObject b:all){if(Store.soon(b))soon++;if(Store.low(b))low++;}LinearLayout stats=card(body);text(stats,all.size()+" confezioni   ·   "+soon+" in scadenza",20,INK);text(stats,low+" sotto scorta minima · avvisi scadenza entro 30 giorni",14,MUTED);button(body,"+ Aggiungi medicinale",this::addChoice);button(body,"Avvisi e scadenze",()->alerts());EditText q=field(body,"Cerca nell’armadietto: nome, AIC o lotto","",false);LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);body.addView(rows);Runnable refresh=()->renderBoxes(rows,store.boxes(q.getText().toString()));watch(q,refresh);refresh.run();button(body,"Backup e informazioni",this::settings);}
 void renderBoxes(LinearLayout rows,List<JSONObject> boxes){rows.removeAllViews();if(boxes.isEmpty()){text(rows,"Nessuna confezione. Aggiungi un medicinale per iniziare.",17,MUTED);return;}for(JSONObject b:boxes){LinearLayout c=card(rows);text(c,b.optString("name"),20,INK).setTypeface(null,Typeface.BOLD);text(c,b.optString("description"),14,MUTED);text(c,number(b.optDouble("qty"))+" "+b.optString("unit")+" · scade "+date(Store.effective(b)),16,INK);String state=Store.soon(b)?(Store.effective(b).isBefore(LocalDate.now())?"Scaduto / oltre il limite d’uso":"Da controllare entro 30 giorni"):"";if(Store.low(b))state+=(state.isEmpty()?"":" · ")+"Scorta bassa";if(!state.isEmpty())text(c,state,14,0xffa14625);c.setOnClickListener(v->detail(b.optLong("id")));}}
 void alerts(){shell("Avvisi","Scadenze e soglie delle singole confezioni");List<JSONObject> rows=new ArrayList<>();for(JSONObject b:store.boxes(""))if(Store.soon(b)||Store.low(b))rows.add(b);if(rows.isEmpty())text(body,"Nessun avviso al momento.",18,INK);else renderBoxes(body,rows);button(body,"Torna all’armadietto",this::home);}
 void addChoice(){new AlertDialog.Builder(this).setTitle("Aggiungi medicinale").setItems(new String[]{"Scansiona codice a barre","Cerca per nome commerciale o AIC"},(d,n)->{if(n==0)startActivityForResult(new Intent(this,ScanActivity.class),10);else search();}).setNegativeButton("Annulla",null).show();}
 void search(){if(catalog==null){error("Attendi la preparazione del catalogo");return;}shell("Trova medicinale","Catalogo AIFA offline · ricerca dal nome commerciale");EditText q=field(body,"Nome commerciale o AIC (almeno 2 caratteri)","",false);LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);body.addView(rows);text(rows,"Scrivi il nome e scegli dosaggio e confezione esatti.",16,MUTED);watch(q,()->{int token=++searchVersion;String term=q.getText().toString();handler.postDelayed(()->{if(token!=searchVersion||!alive)return;worker.execute(()->{try {List<JSONObject> found=catalog.search(term);runOnUiThread(()->{if(!alive||token!=searchVersion||q.getParent()==null)return;rows.removeAllViews();if(term.trim().length()<2){text(rows,"Scrivi almeno 2 caratteri.",16,MUTED);return;}if(found.isEmpty())text(rows,"Nessun risultato. Controlla il nome o prova l’AIC.",16,MUTED);for(JSONObject b:found){LinearLayout c=card(rows);text(c,b.optString("name"),19,INK);text(c,b.optString("description"),15,MUTED);text(c,"AIC "+b.optString("aic")+" · "+b.optString("status"),13,MUTED);c.setOnClickListener(v->confirmDrug(b));}if(found.size()==100)text(rows,"Mostrati 100 risultati: rendi più precisa la ricerca.",14,MUTED);});}catch(Exception e){runOnUiThread(()->error(e.getMessage()));}});},280);});button(body,"Torna all’armadietto",this::home);}
 void confirmDrug(JSONObject drug){new AlertDialog.Builder(this).setTitle("Conferma il medicinale").setMessage(drug.optString("name")+"\n\n"+drug.optString("description")+"\n\nAIC "+drug.optString("aic")+"\nStato AIFA: "+drug.optString("status")+"\n\nVerifica nome, dosaggio e confezione sulla scatola. La presenza nel catalogo non è una raccomandazione d’uso.").setPositiveButton("È la confezione giusta",(d,w)->edit(drug,false)).setNegativeButton("Annulla",null).show();}
 EditText field(LinearLayout p,String label,String value,boolean numeric){text(p,label,14,MUTED);EditText e=new EditText(this);e.setText(value);e.setTextColor(INK);e.setTextSize(17);e.setSingleLine(true);if(numeric)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);p.addView(e,new LinearLayout.LayoutParams(-1,dp(50)));return e;}
 EditText dateField(LinearLayout p,String label,String value,boolean optional){EditText e=field(p,label,value,false);e.setFocusable(false);e.setOnClickListener(v->{LocalDate now;try{now=LocalDate.parse(e.getText().toString());}catch(Exception ex){now=LocalDate.now();}DatePickerDialog dialog=new DatePickerDialog(this,(view,y,m,d)->e.setText(LocalDate.of(y,m+1,d).toString()),now.getYear(),now.getMonthValue()-1,now.getDayOfMonth());if(optional)dialog.setButton(DialogInterface.BUTTON_NEUTRAL,"Non aperta",(d,w)->e.setText(""));dialog.show();});return e;}
 void edit(JSONObject source,boolean existing){shell(existing?"Modifica confezione":"Nuova confezione",source.optString("name"));text(body,source.optString("description")+"\nAIC "+source.optString("aic"),16,INK);text(body,"I dati di questa scatola vanno letti dalla confezione: non vengono dedotti dal codice a barre.",14,MUTED);
 EditText qty=field(body,"Quantità residua",existing?number(source.optDouble("qty")):"",true),unit=field(body,"Unità (compresse, ml, bustine…)",source.optString("unit",""),false),min=field(body,"Soglia minima per questa confezione",existing?number(source.optDouble("minimum")):"",true);
 EditText expiry=dateField(body,"Scadenza (AAAA-MM-GG): se c’è solo mese/anno, scegli l’ultimo giorno del mese",source.optString("expiry",""),false),opened=dateField(body,"Data di apertura (facoltativa)",source.optString("opened",""),true),days=field(body,"Giorni massimi dopo apertura, da foglietto (vuoto se non applicabile)",source.optInt("days",0)>0?""+source.optInt("days"):"",true),lot=field(body,"Lotto (facoltativo)",source.optString("lot",""),false),notes=field(body,"Note (facoltative)",source.optString("notes",""),false);
 button(body,"Salva confezione",()->{try {JSONObject b=new JSONObject();if(existing)b.put("id",source.getLong("id"));for(String k:new String[]{"aic","name","description"})b.put(k,source.getString(k));b.put("qty",decimal(qty));b.put("unit",unit.getText().toString().trim());b.put("minimum",decimal(min));b.put("expiry",expiry.getText().toString());b.put("opened",opened.getText().toString());b.put("days",days.getText().toString().isEmpty()?0:Integer.parseInt(days.getText().toString()));b.put("lot",lot.getText().toString());b.put("notes",notes.getText().toString());Store.validateBox(b);long id=store.save(b);detail(id);}catch(Exception e){error("Controlla i campi: quantità e soglia sono obbligatorie; scegli la scadenza e indica l’unità.\n"+e.getMessage());}});button(body,"Annulla",()->{if(existing)detail(source.optLong("id"));else home();});}
 void detail(long id){JSONObject b=store.box(id);if(b==null){home();return;}shell(b.optString("name"),b.optString("description"));LinearLayout c=card(body);text(c,number(b.optDouble("qty"))+" "+b.optString("unit")+" disponibili",25,INK);text(c,"Scadenza confezione: "+date(LocalDate.parse(b.optString("expiry"))),16,INK);if(!b.optString("opened").isEmpty())text(c,"Aperta il "+date(LocalDate.parse(b.optString("opened"))),16,INK);text(c,"Limite effettivo: "+date(Store.effective(b)),16,INK);text(c,"Scorta minima: "+number(b.optDouble("minimum"))+" "+b.optString("unit")+"\nAIC "+b.optString("aic")+"\nLotto: "+(b.optString("lot").isEmpty()?"non indicato":b.optString("lot")),15,MUTED);if(!b.optString("notes").isEmpty())text(c,b.optString("notes"),16,INK);button(body,"Registra utilizzo",()->useDialog(id));button(body,"Modifica confezione",()->edit(b,true));text(body,"Registro utilizzi",21,INK);List<JSONObject> history=store.history(id);if(history.isEmpty())text(body,"Nessun utilizzo registrato.",15,MUTED);for(JSONObject u:history){LinearLayout row=card(body);String when;try{when=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm").withZone(ZoneId.systemDefault()).format(Instant.parse(u.optString("at")));}catch(Exception e){when=u.optString("at");}text(row,when+" · "+number(u.optDouble("amount"))+" "+b.optString("unit")+(u.optInt("undone")==1?" · annullato":""),16,INK);if(u.optInt("undone")==0)button(row,"Annulla questo utilizzo",()->new AlertDialog.Builder(this).setTitle("Annullare l’utilizzo?").setMessage("La quantità sarà riaggiunta al residuo.").setPositiveButton("Annulla utilizzo",(d,w)->{try{store.undo(u.optLong("id"));detail(id);}catch(Exception e){error(e.getMessage());}}).setNegativeButton("Indietro",null).show());}
 button(body,"Elimina confezione",()->new AlertDialog.Builder(this).setTitle("Eliminare questa confezione?").setMessage("Saranno eliminati anche i suoi utilizzi. Questa operazione non si può annullare.").setPositiveButton("Elimina",(d,w)->{store.delete(id);home();}).setNegativeButton("Mantieni",null).show());button(body,"Torna all’armadietto",this::home);}
 void useDialog(long id){JSONObject b=store.box(id);LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(20),dp(8),dp(20),dp(8));if(Store.effective(b).isBefore(LocalDate.now()))text(form,"Attenzione: confezione oltre la scadenza o il limite dopo apertura. Questa funzione registra un movimento, non indica che il medicinale sia utilizzabile.",16,0xffa14625);EditText amount=field(form,"Quantità da sottrarre ("+b.optString("unit")+")","",true);AlertDialog d=new AlertDialog.Builder(this).setTitle("Registra utilizzo").setView(form).setPositiveButton("Registra",null).setNegativeButton("Annulla",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{store.use(id,decimal(amount));d.dismiss();detail(id);}catch(Exception e){amount.setError(e.getMessage());}}));d.show();}
 void settings(){shell("Backup e informazioni","I tuoi dati restano sul dispositivo");text(body,"Il backup contiene inventario e registro utilizzi, non il catalogo. Conserva il file in un luogo sicuro: non è cifrato dall’app.",16,INK);button(body,"Esporta backup completo",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"farmaci-backup-"+LocalDate.now()+".json");startActivityForResult(i,20);});button(body,"Ripristina un backup",()->new AlertDialog.Builder(this).setTitle("Sostituire i dati attuali?").setMessage("Il ripristino sostituisce tutto l’inventario e lo storico. Esporta prima un backup dei dati presenti.").setPositiveButton("Scegli backup",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,21);}).setNegativeButton("Annulla",null).show());button(body,"Impostazioni notifiche Android",()->{Intent i=new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS);i.putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);});button(body,"Invia notifica di prova",()->ReminderReceiver.notifyNow(this,true));text(body,"Avvisi quotidiani indicativamente alle 09:00: scadenza/limite d’uso entro 30 giorni e soglia minima per confezione. Richiedono il permesso notifiche; Android può ritardarli. Dopo un arresto forzato riapri l’app.",15,MUTED);if(catalog!=null)text(body,"Catalogo AIFA: "+catalog.info.optInt("packages")+" confezioni\nAcquisito: "+catalog.info.optString("downloaded_at")+"\nVersione app 2.0.0\n\nPer aggiornare il catalogo, ricompila e installa il nuovo APK con lo stesso identificativo e la stessa firma: inventario e storico sono separati dal catalogo.",15,MUTED);text(body,"Non è un dispositivo medico e non suggerisce dosi o terapie. Il limite dopo apertura va verificato nel foglietto illustrativo. Scadenze, lotto e quantità non vengono ricavati dall’AIC.",15,MUTED);button(body,"Torna all’armadietto",this::home);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==10){String raw=data.getStringExtra("code");if(catalog==null){error("Catalogo non ancora pronto");return;}for(String code:Codes.candidates(raw==null?"":raw)){JSONObject drug=catalog.find(code);if(drug!=null){confirmDrug(drug);return;}}new AlertDialog.Builder(this).setTitle("Codice non riconosciuto nel catalogo").setMessage("Letto: "+raw+"\nNessun medicinale viene associato per tentativi. Usa la ricerca per nome e verifica la confezione. EAN/GS1 non vengono trasformati arbitrariamente in AIC.").setPositiveButton("Cerca per nome",(d,w)->search()).setNegativeButton("Chiudi",null).show();return;}Uri uri=data.getData();if(uri==null)return;try{if(req==20){byte[] bytes=store.backup().toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("File non accessibile");out.write(bytes);}Toast.makeText(this,"Backup esportato",Toast.LENGTH_LONG).show();}else if(req==21){byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri)){bytes=IO.read(in,25*1024*1024);}JSONObject backup=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));store.restore(backup);Toast.makeText(this,"Backup ripristinato",Toast.LENGTH_LONG).show();home();}}catch(Exception e){error("Operazione non completata: "+e.getMessage());}}
 static String number(double n){return java.math.BigDecimal.valueOf(n).setScale(6,java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();}static String date(LocalDate d){return d.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));}static double decimal(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}
 void watch(EditText e,Runnable r){e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){r.run();}public void afterTextChanged(Editable e){}});}
 void error(String message){new AlertDialog.Builder(this).setTitle("Attenzione").setMessage(message).setPositiveButton("OK",null).show();}
 @Override public void onBackPressed(){home();}
 @Override public void onDestroy(){alive=false;searchVersion++;handler.removeCallbacksAndMessages(null);worker.execute(()->{if(catalog!=null)catalog.close();});worker.shutdown();store.close();super.onDestroy();}
}
